# Import-safety review (TASK-20260929-8218e0): AST inspection of import-time execution, py_compile, audited import.
import ast, os, sys, py_compile, json, subprocess, tempfile
S = os.path.dirname(os.path.abspath(__file__))
IMPL = os.path.join(S, 'impl')
files = sorted(f for f in os.listdir(IMPL) if f.endswith('.py'))
report = {}
def calls_in(node):
    return [n for n in ast.walk(node) if isinstance(n, ast.Call)]
for f in files:
    src = open(os.path.join(IMPL, f), encoding='utf-8').read()
    tree = ast.parse(src)
    issues = []
    kinds = {}
    for st in tree.body:
        k = type(st).__name__
        kinds[k] = kinds.get(k, 0) + 1
        if isinstance(st, (ast.Import, ast.ImportFrom)):
            continue
        if isinstance(st, ast.Expr) and isinstance(st.value, ast.Constant) and isinstance(st.value.value, str):
            continue  # docstring
        if isinstance(st, ast.If):
            t = st.test
            ok = (isinstance(t, ast.Compare) and isinstance(t.left, ast.Name) and t.left.id == '__name__'
                  and isinstance(t.comparators[0], ast.Constant) and t.comparators[0].value == '__main__')
            if not ok:
                issues.append(('module-level if (not main guard)', st.lineno))
            continue
        if isinstance(st, (ast.FunctionDef, ast.AsyncFunctionDef)):
            for d in st.decorator_list:
                issues.append(('decorator evaluated at import', st.lineno, ast.unparse(d)))
            for dflt in st.args.defaults + [x for x in st.args.kw_defaults if x is not None]:
                for c in calls_in(dflt):
                    issues.append(('call in default arg (import-time)', st.lineno, ast.unparse(c)))
            continue
        if isinstance(st, ast.ClassDef):
            for d in st.decorator_list:
                issues.append(('class decorator', st.lineno, ast.unparse(d)))
            for b in st.bases:
                for c in calls_in(b):
                    issues.append(('call in class base', st.lineno, ast.unparse(c)))
            for cst in st.body:
                if isinstance(cst, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    for d in cst.decorator_list:
                        nm = ast.unparse(d)
                        if nm not in ('staticmethod', 'classmethod', 'property'):
                            issues.append(('method decorator', cst.lineno, nm))
                    for dflt in cst.args.defaults + [x for x in cst.args.kw_defaults if x is not None]:
                        for c in calls_in(dflt):
                            issues.append(('call in method default', cst.lineno, ast.unparse(c)))
                elif isinstance(cst, ast.Expr) and isinstance(cst.value, ast.Constant):
                    pass
                else:
                    for c in calls_in(cst):
                        issues.append(('call in class body', cst.lineno, ast.unparse(c)))
            continue
        if isinstance(st, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
            cs = calls_in(st)
            for c in cs:
                issues.append(('call in module-level assignment (import-time)', st.lineno, ast.unparse(c)[:120]))
            continue
        issues.append(('other module-level statement', st.lineno, k, ast.unparse(st)[:120]))
    # py_compile into a temp dir (no write into IMPL)
    with tempfile.TemporaryDirectory() as td:
        try:
            py_compile.compile(os.path.join(IMPL, f), cfile=os.path.join(td, f + 'c'), doraise=True)
            pc = 'ok'
        except py_compile.PyCompileError as e:
            pc = 'FAIL ' + str(e)
    report[f] = {'module_level_kinds': kinds, 'import_time_execution_findings': issues, 'py_compile': pc}
for f, r in report.items():
    print(f, 'py_compile=', r['py_compile'], 'kinds=', r['module_level_kinds'])
    for i in r['import_time_execution_findings']:
        print('    FINDING', i)

