#!/usr/bin/env python3
"""Independent exact-quotient audit recomputation, TASK-20260929-8218e0, joint J1 (ii).

Written by the validator from the ARM DEFINITIONS of EXP-BINSTD-c9c8a2
(definitions.declared_filter_families, definitions.field DF-8,
definitions.normal_basis) and the F1 mid-CDF quantile rule. It shares no code
with the producer's CODE-CORE, CODE-FAM or CODE-AUDIT:
  * field: polynomial basis F_2[t]/(f); irreducibility by Rabin's test; log/exp
    tables over the primitive element t (checked to have full order);
  * normal basis: least normal element w (rank test by numpy elimination),
    coordinates c_j of x = sum c_j w^(2^j) by numpy Gauss-Jordan inverse;
  * points: every x != 0 lifted with a precomputed root table of z^2 + z (no
    half-trace), y = x z and x z + x; x = 0 gives (0, sqrt(B));
  * cosets of 2E and 4E: from a DISCRETE-LOG WALK of a generator of order #E
    (#E counted by the enumeration; cyclicity proved by the walk), so that
    P + 2E <-> dlog mod 2 and P + 4E <-> dlog mod 4. No trace criterion and no
    halving is used to define a coset (the trace criterion is CHECKED against it).
Libraries: Python 3.11 standard library, numpy, sympy (factorint, isprime).
"""
import json
import math
import sys
import time

import numpy as np
import sympy

T19 = (1 << 19) | (1 << 5) | (1 << 2) | (1 << 1) | 1
CELLS = {
    # cid: n, A, B, named polynomial (None -> DF-8 rule), Koblitz?
    "CELL-K13": (13, 0, 1, None, True),
    "CELL-K19": (19, 0, 1, T19, True),
    "CELL-O19": (19, 46693, 306147, T19, False),
    "CELL-K23": (23, 0, 1, None, True),
}
ALPHABETS = {"CELL-K13": (16, 8), "CELL-K19": (64, 16), "CELL-O19": (64, 16),
             "CELL-K23": (128, 32, 16)}


# ------------------------------------------------------------------ field
def mulmod(a, b, f, n):
    """a*b mod f with interleaved reduction (a, b of degree < n)."""
    r = 0
    while b:
        if b & 1:
            r ^= a
        b >>= 1
        a <<= 1
        if (a >> n) & 1:
            a ^= f
    return r


def pmod(a, m):
    dm = m.bit_length() - 1
    while a and a.bit_length() - 1 >= dm:
        a ^= m << (a.bit_length() - 1 - dm)
    return a


def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a


def rabin_irreducible(f, n):
    """f of degree n is irreducible iff t^(2^n) = t mod f and
    gcd(t^(2^(n/p)) - t, f) = 1 for every prime p dividing n."""
    def t_pow_2k(k):
        v = 2
        for _ in range(k):
            v = mulmod(v, v, f, n)
        return v
    if t_pow_2k(n) != 2:
        return False
    for p in sympy.primefactors(n):
        if pgcd(f, t_pow_2k(n // p) ^ 2) != 1:
            return False
    return True


def type2_onb_exists(n):
    """Type-II ONB criterion (recalled; Mullin et al.): p = 2n + 1 prime and
    either 2 primitive mod p, or p = 3 mod 4 and 2 of order n mod p."""
    p = 2 * n + 1
    if not sympy.isprime(p):
        return False
    o = sympy.n_order(2, p)
    return o == 2 * n or (p % 4 == 3 and o == n)


def df8_polynomial(n, named):
    """DF-8: the named polynomial; else (type-II ONB case handled by caller);
    else the lowest-weight irreducible, least as an integer."""
    if named is not None:
        return named, "named"
    if type2_onb_exists(n):
        return None, "type-II ONB exists (not handled here)"
    for weight in (3, 5, 7):
        cands = []
        for mids in __import__("itertools").combinations(range(1, n), weight - 2):
            f = (1 << n) | 1
            for m in mids:
                f |= 1 << m
            cands.append(f)
        for f in sorted(cands):
            if rabin_irreducible(f, n):
                return f, "lowest weight %d, least integer" % weight
    raise ArithmeticError("none found")


class Field:
    def __init__(self, n, f):
        self.n, self.f, self.q = n, f, 1 << n
        q = self.q
        exp = [0] * (2 * (q - 1))
        log = [-1] * q
        v = 1
        for i in range(q - 1):
            if log[v] != -1:
                raise ArithmeticError("t is not primitive")
            exp[i] = v
            log[v] = i
            v <<= 1
            if (v >> n) & 1:
                v ^= f
        if v != 1:
            raise ArithmeticError("t^(q-1) != 1")
        for i in range(q - 1):
            exp[q - 1 + i] = exp[i]
        log[0] = 0  # placeholder, always masked
        self.EXP, self.LOG = exp, log
        self.exp_np = np.array(exp, dtype=np.int64)
        self.log_np = np.array(log, dtype=np.int64)

    # scalar ops
    def mul(self, a, b):
        if a == 0 or b == 0:
            return 0
        return self.EXP[self.LOG[a] + self.LOG[b]]

    def inv(self, a):
        if a == 0:
            raise ZeroDivisionError
        return self.EXP[(self.q - 1 - self.LOG[a]) % (self.q - 1)]

    def sqrt(self, a):
        if a == 0:
            return 0
        return self.EXP[(self.LOG[a] * (self.q >> 1)) % (self.q - 1)]

    def trace_by_powers(self, a):
        s, x = 0, a
        for _ in range(self.n):
            s ^= x
            x = self.mul(x, x)
        assert s in (0, 1)
        return s

    # vector ops
    def vmul(self, a, b):
        a = np.asarray(a, dtype=np.int64)
        b = np.asarray(b, dtype=np.int64)
        r = self.exp_np[self.log_np[a] + self.log_np[b]]
        return np.where((a == 0) | (b == 0), 0, r)

    def vinv(self, a):
        a = np.asarray(a, dtype=np.int64)
        return self.exp_np[(self.q - 1 - self.log_np[a]) % (self.q - 1)]


def f2_rank_np(rows, n):
    m = np.array([[(r >> j) & 1 for j in range(n)] for r in rows], dtype=np.uint8)
    rank, col = 0, 0
    nr = m.shape[0]
    for col in range(n):
        piv = None
        for i in range(rank, nr):
            if m[i, col]:
                piv = i
                break
        if piv is None:
            continue
        m[[rank, piv]] = m[[piv, rank]]
        for i in range(nr):
            if i != rank and m[i, col]:
                m[i] ^= m[rank]
        rank += 1
    return rank


def least_normal_element(F):
    for w in range(1, F.q):
        conj, x = [], w
        for _ in range(F.n):
            conj.append(x)
            x = F.mul(x, x)
        if f2_rank_np(conj, F.n) == F.n:
            return w, conj
    raise ArithmeticError


def nb_tables(F, conj):
    """Coordinates: solve B c = x with B[:, j] = bits of conj[j]."""
    n = F.n
    B = np.array([[(conj[j] >> i) & 1 for j in range(n)] for i in range(n)], dtype=np.uint8)
    aug = np.concatenate([B, np.eye(n, dtype=np.uint8)], axis=1)
    for col in range(n):
        piv = next(i for i in range(col, n) if aug[i, col])
        aug[[col, piv]] = aug[[piv, col]]
        for i in range(n):
            if i != col and aug[i, col]:
                aug[i] ^= aug[col]
    Binv = aug[:, n:]  # c = Binv x
    nb_of_t = []
    for i in range(n):  # image of t^i: column i of Binv, as an int over j
        v = 0
        for j in range(n):
            if Binv[j, i]:
                v |= 1 << j
        nb_of_t.append(v)
    xs = np.arange(F.q, dtype=np.int64)
    table = np.zeros(F.q, dtype=np.int64)
    for i in range(n):
        table ^= ((xs >> i) & 1) * nb_of_t[i]
    return table


# ------------------------------------------------------------------ curve
class Curve:
    def __init__(self, F, A, B):
        self.F, self.A, self.B = F, A, B

    def on_curve(self, P):
        if P is None:
            return True
        F = self.F
        x, y = P
        return (F.mul(y, y) ^ F.mul(x, y)) == (F.mul(F.mul(x, x), x) ^ F.mul(self.A, F.mul(x, x)) ^ self.B)

    def dbl(self, P):
        if P is None:
            return None
        F = self.F
        x1, y1 = P
        if x1 == 0:
            return None
        lam = x1 ^ F.mul(y1, F.inv(x1))
        x3 = F.mul(lam, lam) ^ lam ^ self.A
        y3 = F.mul(x1, x1) ^ F.mul(lam ^ 1, x3)
        return (x3, y3)

    def add(self, P, Q):
        if P is None:
            return Q
        if Q is None:
            return P
        F = self.F
        x1, y1 = P
        x2, y2 = Q
        if x1 == x2:
            if (y1 ^ y2) == x1:
                return None
            return self.dbl(P)
        lam = F.mul(y1 ^ y2, F.inv(x1 ^ x2))
        x3 = F.mul(lam, lam) ^ lam ^ x1 ^ x2 ^ self.A
        y3 = F.mul(lam, x1 ^ x3) ^ x3 ^ y1
        return (x3, y3)

    def smul(self, k, P):
        R = None
        while k:
            if k & 1:
                R = self.add(R, P)
            P = self.dbl(P) if P is not None else None
            k >>= 1
        return R


def enumerate_points(F, A, B):
    q = F.q
    xs = np.arange(1, q, dtype=np.int64)
    x2 = F.vmul(xs, xs)
    cval = xs ^ A ^ F.vmul(np.full_like(xs, B), F.vinv(x2))
    zs = np.arange(q, dtype=np.int64)
    vz = F.vmul(zs, zs) ^ zs
    root = np.full(q, -1, dtype=np.int64)
    root[vz] = zs
    z = root[cval]
    ok = z >= 0
    X = xs[ok]
    Y1 = F.vmul(X, z[ok])
    Y2 = Y1 ^ X
    yB = F.sqrt(B)
    PX = np.concatenate([np.array([0], dtype=np.int64), X, X])
    PY = np.concatenate([np.array([yB], dtype=np.int64), Y1, Y2])
    return PX, PY


def popcount_np(a):
    a = a.astype(np.int64)
    c = np.zeros_like(a)
    while np.any(a):
        c += a & 1
        a = a >> 1
    return c


def weight_buckets_exact(n, M):
    out, acc = [], 0
    den = 1 << (n + 1)
    for w in range(n + 1):
        pw = math.comb(n, w)
        out.append(min(M - 1, (M * (2 * acc + pw)) // den))
        acc += pw
    return np.array(out, dtype=np.int64)


def purity(labels, coset, kmax):
    """Fraction of points in label classes on which coset is constant."""
    lab = np.unique(labels, return_inverse=True)[1]
    ncls = lab.max() + 1
    counts = np.zeros((ncls, kmax), dtype=np.int64)
    np.add.at(counts, (lab, coset), 1)
    sizes = counts.sum(axis=1)
    pure = (counts > 0).sum(axis=1) == 1
    return float(sizes[pure].sum()) / float(sizes.sum()), int(ncls), int(sizes.min())


def run_cell(cid):
    t0 = time.time()
    n, A, B, named, koblitz = CELLS[cid]
    rec = {"cell": cid, "n": n, "A": A, "B": B}
    f, rule = df8_polynomial(n, named)
    if f is None:
        raise SystemExit("type-II case not implemented for %s" % cid)
    assert rabin_irreducible(f, n)
    rec["field_poly"] = f
    rec["field_poly_rule"] = rule
    F = Field(n, f)
    w, conj = least_normal_element(F)
    rec["normal_element"] = w
    nbt = nb_tables(F, conj)
    # self-checks of the coordinates: reconstruction and Frobenius = rotation by one
    rng = np.random.default_rng(12345)
    mask = (1 << n) - 1
    for x in rng.integers(0, F.q, 2000):
        x = int(x)
        c = int(nbt[x])
        recon = 0
        for j in range(n):
            if (c >> j) & 1:
                recon ^= conj[j]
        assert recon == x
        c2 = int(nbt[F.mul(x, x)])
        assert c2 == (((c << 1) | (c >> (n - 1))) & mask)
    C = Curve(F, A, B)
    PX, PY = enumerate_points(F, A, B)
    naff = len(PX)
    N = naff + 1
    rec["affine_points"] = naff
    rec["order_by_enumeration"] = N
    fac = sympy.factorint(N)
    rec["factorisation_sympy"] = {str(k): v for k, v in sorted(fac.items())}
    # every enumerated point on the curve (sampled check of 5000) and all distinct
    keys = (PX << n) | PY
    assert len(np.unique(keys)) == naff
    for i in rng.integers(0, naff, 5000):
        assert C.on_curve((int(PX[i]), int(PY[i])))
    # a generator of order N
    import random as _r
    R = _r.Random(zlib_seed(cid))
    g = None
    for _ in range(1000):
        i = R.randrange(naff)
        P = (int(PX[i]), int(PY[i]))
        if C.smul(N, P) is not None:
            raise ArithmeticError("N does not annihilate a point")
        if all(C.smul(N // p, P) is not None for p in fac):
            g = P
            break
    assert g is not None, "no generator: group not cyclic?"
    rec["generator"] = list(g)
    # discrete-log walk
    dlog = {}
    P = None
    for i in range(N):
        k = -1 if P is None else (P[0] << n) | P[1]
        if k in dlog:
            raise ArithmeticError("walk repeats")
        dlog[k] = i
        P = C.add(P, g)
    assert P is None and len(dlog) == N
    D = np.fromiter((dlog[int(k)] for k in keys), dtype=np.int64, count=naff)
    coset2 = D & 1
    coset4 = D & 3
    # check of the trace criterion (PO-2) and of the NB-trace identity (DF-9) against the walk
    trA = F.trace_by_powers(A)
    tr_tab = np.array([0] * 1, dtype=np.int64)
    trace_bits = np.zeros(n, dtype=np.int64)
    for i in range(n):
        trace_bits[i] = F.trace_by_powers(1 << i)
    tmask = int(sum(int(trace_bits[i]) << i for i in range(n)))
    trx = popcount_np(PX & tmask) & 1
    h2_trace = trx ^ trA
    rec["PO2_trace_criterion_equals_walk_coset2_on_every_point"] = bool(np.all(h2_trace == coset2))
    c_all = nbt[PX]
    wt = popcount_np(c_all)
    rec["DF9_nb_weight_parity_equals_trace_on_every_point"] = bool(np.all((wt & 1) == trx))
    rec["Tr_A"] = int(trA)
    # labels and purities
    rows = []
    for M in ALPHABETS[cid]:
        r = M.bit_length() - 1
        offs = (0, (n - r) // 2, n - r)
        wb = weight_buckets_exact(n, M)
        arms = []
        if koblitz:
            arms.append(("F1", None, wb[wt]))
        for o in offs:
            lab = np.zeros(naff, dtype=np.int64)
            for k in range(r):
                lab |= ((c_all >> ((o + k) % n)) & 1) << k
            arms.append(("F2" if koblitz else "ORD-F2", o, lab))
        for o in offs:
            arms.append(("F3" if koblitz else "ORD-F3", o, (PX >> o) & (M - 1)))
        if koblitz:
            mr = c_all.copy()
            for k in range(1, n):
                rot = ((c_all >> k) | (c_all << (n - k))) & mask
                mr = np.minimum(mr, rot)
            arms.append(("F4", None, mr >> (n - r)))
            r4 = r - 2
            m4 = (M // 4) - 1
            wb4 = weight_buckets_exact(n, M // 4)
            arms.append(("F5xF1", None, wb4[wt] * 4 + coset4))
            arms.append(("F5xF2", 0, (c_all & m4) * 4 + coset4))
            arms.append(("F5xF3", 0, (PX & m4) * 4 + coset4))
            arms.append(("F5xF4", None, (mr >> (n - r4)) * 4 + coset4))
        for name, o, lab in arms:
            p2, ncls, smallest = purity(lab, coset2, 2)
            row = {"cell": cid, "arm": name, "offset": o, "M": M, "points": naff,
                   "classes": ncls, "smallest_class": smallest, "purity_2": p2}
            if koblitz:
                row["purity_4"] = purity(lab, coset4, 4)[0]
            rows.append(row)
    rec["seconds"] = round(time.time() - t0, 1)
    return rec, rows


def zlib_seed(s):
    import zlib
    return zlib.crc32(("validator-8218e0:" + s).encode("ascii"))


if __name__ == "__main__":
    out = {"cells": [], "rows": []}
    for cid in sys.argv[1:]:
        rec, rows = run_cell(cid)
        out["cells"].append(rec)
        out["rows"].extend(rows)
        print(json.dumps({"cell_meta": rec}), flush=True)
        for row in rows:
