scripts.compare_c4.py:
# Compare the producer's frozen C-4 table (audit sheet design_computations.C-4.output) with
# the validator's independent enumeration (my_audit_*.jsonl). TASK-20260929-8218e0, J1 (ii).
import json, yaml, hashlib
d = yaml.safe_load(open('src/audit_v3.yaml'))['proof_search_map_audit']
c4 = d['design_computations']['C-4']
out = c4['output']
print('C-4 output bytes', len(out.encode()), 'sha256 of embedded text', hashlib.sha256(out.encode()).hexdigest(), '(stated stdout_sha256', c4['stdout_sha256'].split()[0], ')')
prod = {}
metas = []
for line in out.strip().split('\n'):
    j = json.loads(line)
    if 'cell_meta' in j:
        metas.append(j['cell_meta']); continue
    if 'exact_carrying' in j and 'arm' not in j:
        print('producer exact_carrying list:', j['exact_carrying']); continue
    off = j['offset']
    prod[(j['cell'], j['M'], j['arm'], None if off is None else int(off))] = j
mine = {}
mymeta = {}
for f in ('my_audit_K13.jsonl', 'my_audit_K19.jsonl', 'my_audit_O19.jsonl'):
    for line in open(f):
        j = json.loads(line)
        if 'cell_meta' in j:
            mymeta[j['cell_meta']['cell']] = j['cell_meta']; continue
        mine[(j['cell'], j['M'], j['arm'], j['offset'])] = j
print('producer metas:')
for m in metas: print('  ', m)
for cid, m in mymeta.items():
    pm = [x for x in metas if x['cell'] == cid][0]
    print('META %s field_poly mine=%s prod=%s | normal_element mine=%s prod=%s | points mine=%s prod=%s' % (cid, m['field_poly'], pm['field_poly'], m['normal_element'], pm['normal_element'], m['affine_points'], pm['points']))
nexact = 0; ndiff = 0
for key, mr in sorted(mine.items(), key=lambda kv: (kv[0][0], -kv[0][1], kv[0][2], -1 if kv[0][3] is None else kv[0][3])):
    pr = prod.get(key)
    if pr is None:
        print('MISSING in producer table:', key); ndiff += 1; continue
    diffs = []
    for fld in ('points', 'classes', 'smallest_class'):
        if mr[fld] != pr[fld]: diffs.append((fld, mr[fld], pr[fld]))
    # producer rounds to 6 decimals
    if abs(round(mr['purity_2'], 6) - pr['purity_2']) > 1e-12: diffs.append(('purity_2', mr['purity_2'], pr['purity_2']))
    if 'purity_4' in mr:
        if pr['purity_4'] is None or abs(round(mr['purity_4'], 6) - pr['purity_4']) > 1e-12: diffs.append(('purity_4', mr['purity_4'], pr['purity_4']))
    elif pr['purity_4'] is not None:
        diffs.append(('purity_4', None, pr['purity_4']))
    flag_mine = mr['purity_2'] >= 0.05 or (mr.get('purity_4') or 0) >= 0.05
    if flag_mine != pr['exact_carrying']: diffs.append(('exact_carrying', flag_mine, pr['exact_carrying']))
    if diffs:
        ndiff += 1; print('DIFF', key, diffs)
    else:
        nexact += 1
extra = [k for k in prod if k[0] in mymeta and k not in mine]
print('rows compared: %d; identical (to the producer\'s 6 printed decimals, classes, smallest class, flag): %d; differing: %d; producer rows on these cells not in mine: %s' % (len(mine), nexact, ndiff, extra))
# sampled rows of the producer for K23/K41
print('producer sampled rows:')
for key, pr in sorted(prod.items(), key=lambda kv: (kv[0][0], -kv[0][1], kv[0][2], -1 if kv[0][3] is None else kv[0][3])):
    if key[0] in ('CELL-K23', 'CELL-K41'):
        print('  %-9s M=%-4d %-7s off=%-5s cls=%-4s p2=%s se2=%s p4=%s se4=%s flag=%s' % (key[0], key[1], key[2], key[3], pr['classes'], pr['purity_2'], pr['se_2'], pr['purity_4'], pr['se_4'], pr['exact_carrying']))

