NUM = re.compile(r'(?<![A-Za-z0-9_-])[-+]?\d+(?:\.\d+)?(?:e[-+]?\d+)?')
def nums(s):
    return sorted(set(NUM.findall(str(s))))
def walk(a, b, path, out):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in a:
            if k not in b:
                out.append(('ONLY_V2', path + [k], a[k], None))
            else:
                walk(a[k], b[k], path + [k], out)
        for k in b:
            if k not in a:
                out.append(('ONLY_V3', path + [k], None, b[k]))
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            out.append(('LIST_LEN', path, len(a), len(b)))
        for i in range(min(len(a), len(b))):
            walk(a[i], b[i], path + [i], out)
        for i in range(min(len(a), len(b)), len(a)):
            out.append(('ONLY_V2', path + [i], a[i], None))
        for i in range(min(len(a), len(b)), len(b)):
            out.append(('ONLY_V3', path + [i], None, b[i]))
    else:
        if a != b:
            kind = 'VALUE'
            if isinstance(a, str) and isinstance(b, str):
                na, nb = nums(a), nums(b)
                kind = 'TEXT_SAME_NUMBERS' if na == nb else 'TEXT_NUMBERS_DIFFER'
            out.append((kind, path, a, b))
BLOCKS = [('pinned_inputs',), ('budget_quantity_statement',), ('capacity_certificate',), ('ideal_tree_table',),
          ('design_corrections',), ('heur_b2_thresholds',), ('koblitz_orders',), ('ladder_choice',),
          ('sample_table',), ('closed_form_needs',), ('null_scale',), ('resolving_floor',), ('bootstrap_removal',)]
allres = {}
for blk in BLOCKS:
    a = v2['stage_0'].get(blk[0]); b = v3['stage_0'].get(blk[0])
    out = []
    walk(a, b, ['stage_0', blk[0]], out)
    allres[blk[0]] = out
    print('=' * 100)
    print('BLOCK stage_0.%s : %d difference(s)' % (blk[0], len(out)))
    for kind, path, x, y in out:
        p = '.'.join(str(t) for t in path)
        if kind in ('TEXT_SAME_NUMBERS',):
            print('  [%s] %s' % (kind, p))
        elif kind in ('TEXT_NUMBERS_DIFFER',):
            na, nb = nums(x), nums(y)
            print('  [%s] %s\n      numbers only in v2: %s\n      numbers only in v3: %s' % (kind, p, sorted(set(na) - set(nb)), sorted(set(nb) - set(na))))
        else:
            xs = json.dumps(x, default=str); ys = json.dumps(y, default=str)
            print('  [%s] %s\n      v2: %s\n      v3: %s' % (kind, p, xs[:400], ys[:400]))

