# PO-1 falsification attempt (TASK-20260929-8218e0, J1 certificate support): on every abelian group of
# order <= 12, enumerate ALL surjective labels h: G -> {0..M-1} (up to relabelling, restricted-growth order)
# that are EXACTLY sum-compatible with a combining rule f invertible in each argument, by backtracking.
# Check: solutions exist iff M | |G|, and every solution's fibres are the cosets of a subgroup of index M.
import itertools, time
def groups():
    out = []
    for n in range(2, 13):
        out.append(((n,), "Z/%d" % n))
    for dims in ((2, 2), (2, 4), (3, 3), (2, 6), (2, 2, 2), (2, 2, 3)):
        out.append((dims, "x".join("Z/%d" % d for d in dims)))
    return out
def elements(dims):
    return list(itertools.product(*[range(d) for d in dims]))
def solve(dims, M):
    els = elements(dims); n = len(els); idx = {e: i for i, e in enumerate(els)}
    add = [[idx[tuple((a + b) % d for a, b, d in zip(els[i], els[j], dims))] for j in range(n)] for i in range(n)]
    h = [-1] * n; f = {}; sols = []
    rowv = [dict() for _ in range(M)]; colv = [dict() for _ in range(M)]   # f[a][b]=c ; injectivity per row/col
    def consistent_assign(i):
        # check all pairs (p, q) with p, q, p+q assigned where i is involved
        added = []
        ok = True
        for p in range(n):
            if h[p] < 0: continue
            for (P, Q) in ((i, p), (p, i)):
                R = add[P][Q]
                if h[R] < 0: continue
                a, b, c = h[P], h[Q], h[R]
                key = (a, b)
                if key in f:
                    if f[key] != c: ok = False; break
                else:
                    if c in rowv[a] and rowv[a][c] != b: ok = False; break
                    if c in colv[b] and colv[b][c] != a: ok = False; break
                    f[key] = c; rowv[a][c] = b; colv[b][c] = a; added.append(key)
            if not ok: break
            # also pairs where i is the sum
        if ok:
            for P in range(n):
                for Q in range(n):
                    if add[P][Q] == i and h[P] >= 0 and h[Q] >= 0:
                        a, b, c = h[P], h[Q], h[i]
                        key = (a, b)
                        if key in f:
                            if f[key] != c: ok = False; break
                        else:
                            if c in rowv[a] and rowv[a][c] != b: ok = False; break
                            if c in colv[b] and colv[b][c] != a: ok = False; break
                            f[key] = c; rowv[a][c] = b; colv[b][c] = a; added.append(key)
                if not ok: break
        return ok, added
    def undo(added):
        for key in added:
            a, b = key; c = f.pop(key); del rowv[a][c]; del colv[b][c]
    def rec(i, used):
        if i == n:
            if used == M: sols.append(tuple(h))
            return
        if M - used > n - i: return
        for lab in range(min(used + 1, M)):
            h[i] = lab
            ok, added = consistent_assign(i)
            if ok: rec(i + 1, max(used, lab + 1))
            undo(added); h[i] = -1
    rec(0, 0)
    return els, add, sols
def is_hom_fibres(els, add, sol, M):
    n = len(els)
    K = [i for i in range(n) if sol[i] == sol[0]]          # fibre of the identity (element 0 is the identity)
    Kset = set(K)
    if not all(add[a][b] in Kset for a in K for b in K): return False     # K a subgroup
    for i in range(n):                                       # fibres are cosets of K
        fib = {j for j in range(n) if sol[j] == sol[i]}
        if fib != {add[i][k] for k in K}: return False
    return len(K) * M == n
t0 = time.time(); bad = []; summary = []
for dims, name in groups():
    N = 1
    for d in dims: N *= d
    for M in range(2, N):
        els, add, sols = solve(dims, M)
        homs = all(is_hom_fibres(els, add, s, M) for s in sols)
        divides = N % M == 0
        if (len(sols) > 0) != divides or not homs:
            bad.append((name, M, len(sols), divides, homs))
        summary.append((name, M, len(sols)))
print("groups checked:", len(groups()), "; (group, M) pairs:", len(summary), "; seconds:", round(time.time() - t0, 1))
print("violations of 'exists iff M | |G|, and every solution is a homomorphism':", bad)
print("examples (group, M, number of solutions up to relabelling):", [s for s in summary if s[2] > 0][:12])

