# J2 review computation (TASK-20260929-8218e0): dry call of the committed CODE-FAM stage3 and
# heur_b2_held_out on SYNTHETIC rows (no curve, no gain), to test whether a declared F2/F3 arm at the
# middle or end offset is one arm across cells.
import sys, math, json
sys.path.insert(0, 'impl')
import estimator as est
import families as fam
CELLS = {"CELL-K13": (13, True, (16, 8)), "CELL-K19": (19, True, (64, 16)), "CELL-K23": (23, True, (128, 32, 16)),
         "CELL-K41": (41, True, (16,)), "CELL-O19": (19, False, (64, 16))}
LOG2 = [math.log2(2003), math.log2(130873), math.log2(2095853)]
NULL = {"q50": 6.0, "q99": 7.0, "W": 1.0, "draws": 500, "V": [0.5] * 10}
def rows(strong, z=0.0):
    out = []
    for s in range(10):
        if strong:
            out.append({"seed": s, "G": 20.0, "E_RL": 10.0, "E_Sh": 10.0, "p": 1 / 11, "V": 0.5, "Z": z, "used": 200, "excluded": 0, "estimated": True})
        else:
            out.append({"seed": s, "G": 6.0, "E_RL": 0.0, "E_Sh": 0.0, "p": 1.0, "V": 0.5, "Z": 0.0, "used": 200, "excluded": 0, "estimated": True})
    return out
# Declared arm identity by ROLE: F2 at the middle offset floor((n - r)/2) on every cell.
def mid(n, M):
    r = M.bit_length() - 1
    return (n - r) // 2
names_by_cell = {}
outs = {}
for cid, (n, kob, Ms) in CELLS.items():
    outs[cid] = {}
    for M in Ms:
        for name in fam.family_names(kob, n, M):
            names_by_cell.setdefault(name, []).append((cid, M))
            strong = False
            z = 0.0
            lead = (cid, M) in [("CELL-K13", 16), ("CELL-K19", 64), ("CELL-K23", 128)]
            # plant the SAME strong, growing excess on F2@0 and on the declared F2 middle-offset arm, at the lead keys only
            if lead and (name == "F2@0" or name == "F2@%d" % mid(n, M)):
                strong = True
                z = {"CELL-K13": 10.0, "CELL-K19": 20.0, "CELL-K23": 30.0}[cid]
            outs[cid][(name, M)] = {"rows": rows(strong, z), "null": NULL, "image_sizes": [M] * 10}
res = fam.stage3(outs, LOG2)
print("distinct Koblitz arm names produced by family_names over the declared (cell, M):",
      len([k for k in names_by_cell if not k.startswith("ORD-")]), "(the contract declares twelve Koblitz arms)")
print("F2/F3 names and the (cell, M) each covers:")
for k in sorted(names_by_cell):
    if k.startswith("F2@") or k.startswith("F3@"):
        print("   %-7s %s" % (k, names_by_cell[k]))
mids = {cid: mid(CELLS[cid][0], LEAD) for cid, LEAD in [("CELL-K13", 16), ("CELL-K19", 64), ("CELL-K23", 128)]}
print("declared F2 middle offset at the three lead keys:", mids)
for nm in ["F2@0"] + ["F2@%d" % v for v in sorted(set(mids.values()))]:
    v = res["verdicts"][nm]
    print("stage3 verdict for %-6s -> %s ; ladder classification applied: %s" % (nm, v["verdict"], "per_cell" in v))
hb = res["heur_b2_held_out"]
for nm in ["F2@0", "F2@4", "F2@6", "F2@8", "F2@9", "F2@18"]:
    print("heur_b2_held_out %-6s -> %s" % (nm, hb.get(nm)))
print("number of names heur_b2_held_out reports (contract: twelve declared Koblitz arms):", len(hb))
